class Solution:
    def closestPrices(self, prices: List[int], k: int, x: int) -> List[int]:
        ranked = sorted(prices, key=lambda p: (abs(p - x), p))
        return sorted(ranked[:k])

code.java:
class Solution {
    public int[] closestPrices(int[] prices, int k, int x) {
        Integer[] ranked = Arrays.stream(prices).boxed().toArray(Integer[]::new);
        Arrays.sort(ranked, (a, b) -> {
            long da = Math.abs((long) a - x), db = Math.abs((long) b - x);
            return da != db ? Long.compare(da, db) : Integer.compare(a, b);
        });
        int[] out = new int[k];
        for (int i = 0; i < k; i++) out[i] = ranked[i];
        Arrays.sort(out);
        return out;
    }
}

