class Solution {
public:
    vector<int> closestPrices(vector<int>& prices, int k, int x) {
        vector<int> ranked = prices;
        sort(ranked.begin(), ranked.end(), [x](int a, int b) {
            long long da = llabs((long long) a - x), db = llabs((long long) b - x);
            return da != db ? da < db : a < b;
        });
        vector<int> out(ranked.begin(), ranked.begin() + k);
        sort(out.begin(), out.end());
        return out;
    }
};

