static int gX;

static int byCloseness(const void* pa, const void* pb) {
    int a = *(const int*) pa, b = *(const int*) pb;
    long long da = llabs((long long) a - gX), db = llabs((long long) b - gX);
    if (da != db) return da < db ? -1 : 1;
    return (a > b) - (a < b);
}

static int cmpInt(const void* pa, const void* pb) {
    int a = *(const int*) pa, b = *(const int*) pb;
    return (a > b) - (a < b);
}

int* closestPrices(int* prices, int pricesSize, int k, int x, int* returnSize) {
    int* ranked = malloc(pricesSize * sizeof(int));
    memcpy(ranked, prices, pricesSize * sizeof(int));
    gX = x;
    qsort(ranked, pricesSize, sizeof(int), byCloseness);
    qsort(ranked, k, sizeof(int), cmpInt);
    *returnSize = k;
    return ranked;
}

