class Solution:
    def closestPrices(self, prices: List[int], k: int, x: int) -> List[int]:
        lo, hi = 0, len(prices) - 1
        while hi - lo + 1 > k:
            if x - prices[lo] > prices[hi] - x:
                lo += 1
            else:
                hi -= 1
        return prices[lo:hi + 1]

