class Solution {
    public int[] closestPrices(int[] prices, int k, int x) {
        int lo = 0, hi = prices.length - 1;
        while (hi - lo + 1 > k) {
            if ((long) x - prices[lo] > (long) prices[hi] - x) lo++;
            else hi--;
        }
        return Arrays.copyOfRange(prices, lo, hi + 1);
    }
}

